                    classes[name] = digest(z.read(name))
    if classes != reference['runtimeClassesSha256']:
        raise ValueError('Serving game classes differ from the preserved run')
    for name, expected in reference['sourceSha256'].items():
        if digest((ROOT/name).read_bytes()) != expected:
            raise ValueError('Source changed: ' + name)
    with socket.socket() as check:
        check.bind(('127.0.0.1', args.port))  # Refuse to disturb an existing instance.
    with urllib.request.urlopen('http://localhost:11434/api/tags', timeout=3) as r:
        model = next(m for m in json.load(r)['models'] if m['name'] == 'tev1:0.8b')
    if model['digest'] != reference['localModels'][0]['digest']:
        raise ValueError('Model weights differ from the preserved run')
    out.mkdir(parents=True, exist_ok=False)  # Never overwrite an earlier capture.
    work = ROOT/'.work'/out.name
    work.mkdir(parents=True, exist_ok=True)
    lock, exchanges = threading.Lock(), []
    hop = {'host', 'connection', 'keep-alive', 'transfer-encoding', 'te', 'trailer',
